-- Vashj'ir spawns, part 3 of 6: the rows of this part are deleted by key range before they are inserted, so the file can run twice.
-- Based on Legends of Azeroth 5.4.8 and The Cataclysm Preservation Project 4.3.4.

DELETE FROM `creature` WHERE `guid` BETWEEN 9264000 AND 9264859;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 9260010 AND 9264821;







